/* Original exam-style teaching; Year 11 force and impulse scenario journeys. */
(function(){'use strict'; const C=window.PhysicsScenarioCourse,H=C.helpers;
const {esc,math:E,paper,reveal:R,svg,text,line,arrow,ball,number,check}=H;
const P=x=>'<p>'+x+'</p>';const mark=ps=>'<table class="pf-marking"><thead><tr><th>Reasoning and working</th><th>Marks</th></tr></thead><tbody>'+ps.map(p=>'<tr><td>'+esc(p)+'</td><td>1</td></tr>').join('')+'</tbody></table>';
function diagram(kind){let b='';
if(kind==='pair'){b='<rect x="100" y="170" width="110" height="100" fill="#dcebf3"/><rect x="480" y="170" width="150" height="100" fill="#e6f2e9"/>'+arrow(150,210,65,210,'#0b8774')+arrow(555,210,690,210,'#2a6bb2')+text(90,145,'Object A; mass mA')+text(470,145,'Object B; mass mB')+text(100,320,'← Force ON A BY B')+text(400,360,'Force ON B BY A →')+text(80,55,'Equal interaction magnitudes; different receiving objects')+text(90,420,'Separate diagrams: the pair does not cancel on either object.');}
if(kind==='lift'||kind==='contact'){b=ball(320,180,25)+arrow(320,155,320,65,'#0b8774')+arrow(320,205,320,325,'#c87518')+text(370,100,kind==='lift'?'N or T upward':'contact force upward')+text(370,305,'mg downward')+text(80,45,'Forces on selected person / ball; up positive')+text(100,385,'Fcontact − mg = ma; acceleration is not a force arrow.');}
if(kind==='friction'){b=line(70,300,700,300)+'<rect x="260" y="215" width="120" height="80" fill="#dcebf3"/>'+arrow(380,235,540,145,'#2a6bb2')+arrow(320,215,320,110,'#0b8774')+arrow(320,295,320,390,'#c87518')+arrow(260,260,120,260,'#a15bb5')+text(450,125,'F at angle θ above horizontal')+text(345,115,'N')+text(345,385,'mg')+text(95,240,'friction ←')+text(80,45,'Sliding right; schematic forces on block')+text(90,445,'Vertical balance: N = mg − F sinθ.');}
if(kind==='pulley'){b=line(80,230,470,230)+line(470,230,470,410)+'<rect x="180" y="165" width="115" height="60" fill="#dcebf3"/>'+ball(485,195,18)+line(295,190,485,190)+line(500,195,500,300)+'<rect x="460" y="300" width="80" height="65" fill="#e6f2e9"/>'+arrow(295,165,390,165,'#0b8774')+arrow(570,340,570,260,'#0b8774')+arrow(500,365,500,430,'#c87518')+text(160,140,'table mass m1')+text(350,145,'T →')+text(590,285,'T ↑')+text(540,415,'m2g ↓')+text(80,45,'Ideal rope and fixed pulley; hanging mass m2')+text(80,480,'Compatible path axes: table right; hanging down.');}
if(kind==='rebound'){b='<rect x="620" y="90" width="20" height="230" fill="#cedbe4"/>'+ball(140,155,15)+arrow(165,155,480,155,'#0b8774')+ball(140,290,15)+arrow(480,290,165,290,'#2a6bb2')+text(200,125,'Before: positive towards wall')+text(200,330,'After: negative away from wall')+text(80,45,'Choose + right; outgoing speed must become negative velocity')+text(80,405,'Δp = m(v − u); rebound gives a larger change than stopping.');}
if(kind==='graph'){b=arrow(100,330,700,330)+arrow(100,330,100,65,'#2a6bb2')+'<path d="M150 330L390 100L630 330Z" fill="#e6f2e9" stroke="#c87518" stroke-width="4"/>'+text(90,45,'Net force (N)')+text(390,80,'100 N','#18374d','middle')+text(150,370,'0','#18374d','middle')+text(630,370,'0.200 s','#18374d','middle')+text(250,285,'Signed area = impulse')+text(90,425,'Triangle: J = ½ × 100 × 0.200 = 10.0 N·s');}
return svg('Labelled '+kind+' model; force directions and quantities stated',b,kind==='pulley'?510:480);}
function detail(kind){let b='';
if(kind==='pair')b='<rect x="180" y="180" width="100" height="85" fill="#dcebf3"/><rect x="280" y="180" width="150" height="85" fill="#e6f2e9"/>'+arrow(70,215,170,215)+arrow(290,140,405,140,'#2a6bb2')+text(80,100,'external push 30.0 N →')+text(180,300,'2.00 kg')+text(300,300,'3.00 kg')+text(285,120,'contact on 3 kg: 18.0 N →')+text(80,380,'Shared a = 6.00 m/s²; internal contact differs from push.');
if(kind==='lift')b=text(80,75,'Same 60.0 kg passenger; compare signed accelerations')+text(90,105,'a = +1.50 m/s²')+arrow(180,210,180,120)+text(90,275,'N = 678 N')+text(405,160,'a = −1.50 m/s²')+arrow(500,190,500,280,'#2a6bb2')+text(405,340,'N = 498 N')+text(80,420,'Acceleration arrows are shown separately from free-body forces.');
if(kind==='friction')b=arrow(150,280,450,107,'#c87518')+arrow(150,280,450,280)+line(450,280,450,107,'#2a6bb2',true)+text(270,80,'F = 50.0 N at 30°')+text(200,320,'Fx = 43.3 N')+text(475,180,'Fy = 25.0 N')+text(190,250,'30°')+text(80,400,'10 kg crate: N = 98 − 25 = 73 N when pulling up.');
if(kind==='pulley')b=ball(375,90,25)+line(350,90,350,180)+line(400,90,400,180)+'<rect x="295" y="180" width="70" height="95" fill="#dcebf3"/><rect x="385" y="180" width="70" height="65" fill="#e6f2e9"/>'+arrow(275,195,275,300,'#c87518')+arrow(475,250,475,155)+text(100,190,'5 kg down')+text(490,180,'3 kg up')+text(120,365,'a = (5 − 3)g/(5 + 3) = 2.45 m/s²')+text(120,410,'T = 36.75 N on both sides of ideal rope.');
if(kind==='rebound')b=arrow(350,130,590,130)+arrow(350,245,190,245,'#2a6bb2')+arrow(350,350,70,350,'#c87518')+text(80,85,'0.200 kg ball; signed momenta and change')+text(385,110,'initial p = +2.40 kg·m/s')+text(170,280,'final p = −1.60 kg·m/s')+text(80,395,'Δp = −4.00 kg·m/s; negative change, not a speed.');
if(kind==='graph')b=arrow(100,230,680,230)+arrow(100,360,100,50,'#2a6bb2')+'<path d="M100 230V110H300V230H600V310H300V230" fill="none" stroke="#c87518" stroke-width="4"/>'+text(110,45,'Net force (N)')+text(120,95,'+6 N for 2 s')+text(355,345,'−4 N for 3 s')+text(100,400,'J1 = +12 N·s; J2 = −12 N·s; total J = 0.')+text(340,215,'t = 2 s')+text(580,215,'5 s');
if(kind==='contact')b=text(80,75,'Same 60 kg person; stop from −4 m/s to rest')+text(80,150,'Short stop: 0.20 s')+text(405,150,'Long stop: 0.50 s')+arrow(210,350,210,185,'#c87518')+arrow(535,350,535,250)+text(80,390,'Ground average 1788 N')+text(405,390,'Ground average 1068 N')+text(80,440,'Same net impulse +240 N·s. Arrow lengths schematic.');
return svg('Additional labelled '+kind+' worked scenario',b,490);}
function workedDiagram(kind){let b='';
if(kind==='pair')b=text(80,55,'Skaters: same 120 N interaction, different response')+ball(210,190,28,'#dcebf3')+ball(520,190,38,'#e6f2e9')+arrow(180,190,80,190,'#2a6bb2')+arrow(565,190,665,190)+text(90,150,'120 N ←')+text(575,150,'→ 120 N')+text(130,275,'40.0 kg; a = 3.00 m/s²')+text(420,315,'80.0 kg; a = 1.50 m/s²')+text(80,400,'Lighter skater: twice the acceleration magnitude, not twice force.');
if(kind==='lift')b=text(80,55,'60 kg passenger descending but slowing; up positive')+ball(240,215,25)+arrow(240,190,240,80)+arrow(240,240,240,335,'#c87518')+text(275,110,'N = 678 N upward')+text(275,335,'mg = 588 N downward')+arrow(610,210,610,120,'#2a6bb2')+text(465,145,'a = +1.50 m/s²')+text(470,270,'v is downward')+text(80,415,'Net force = 678 − 588 = +90 N = 60 × 1.50.');
if(kind==='friction')b=text(80,55,'10 kg crate: compare sticking and sliding')+'<rect x="135" y="170" width="95" height="65" fill="#dcebf3"/><rect x="465" y="170" width="95" height="65" fill="#e6f2e9"/>'+arrow(230,195,325,195)+arrow(135,215,40,215,'#a15bb5')+arrow(560,195,700,195)+arrow(465,215,385,215,'#a15bb5')+text(85,135,'Rest: applied 30 N →')+text(405,135,'Sliding: applied 50 N →')+text(80,280,'actual static friction 30 N ←')+text(410,320,'kinetic friction 29.4 N ←')+text(80,400,'Static maximum 39.2 N; sliding net 20.6 N right.');
if(kind==='pulley')b=text(80,45,'Separate free-body diagrams: 3 kg table; 2 kg hanging')+ball(200,220,25,'#dcebf3')+arrow(200,190,200,95)+arrow(200,250,200,350,'#c87518')+arrow(230,220,350,220,'#2a6bb2')+text(225,100,'N = 29.4 N ↑')+text(215,370,'m1g = 29.4 N ↓')+text(275,190,'T = 11.76 N →')+ball(560,220,25,'#e6f2e9')+arrow(560,190,560,110,'#2a6bb2')+arrow(560,250,560,365,'#c87518')+text(440,90,'T = 11.76 N ↑')+text(455,395,'m2g = 19.6 N ↓')+text(80,455,'Table: T = m1a. Hanging: m2g − T = m2a.');
if(kind==='rebound')b=text(80,55,'Same 0.5 kg ball; compare stop and rebound')+text(80,140,'Incoming: u = +8 m/s')+arrow(330,130,550,130)+text(80,230,'Stop: final v = 0')+text(360,230,'J = −4 N·s')+text(80,325,'Rebound: v = −8 m/s')+arrow(570,315,350,315,'#2a6bb2')+text(360,360,'J = −8 N·s')+text(80,430,'Rebound adds outgoing opposite momentum to stopping change.');
if(kind==='graph')b=text(80,45,'Trapezium then rectangle: two positive impulse areas')+arrow(100,330,690,330)+arrow(100,330,100,80,'#2a6bb2')+'<path d="M100 330V260L450 120H590V330Z" fill="#e6f2e9" stroke="#c87518" stroke-width="4"/>'+line(450,120,450,330,'#526d82',true)+text(115,290,'20 N')+text(465,100,'60 N')+text(100,370,'0')+text(395,370,'0.050 s')+text(560,410,'0.070 s')+text(80,465,'First area 2.00 N·s + second area 1.20 N·s = 3.20 N·s.');
if(kind==='contact')b=text(80,45,'60 kg person landing; distinguish real forces and net result')+ball(240,230,25)+arrow(240,205,240,80)+arrow(240,255,240,340,'#c87518')+text(280,100,'Ground average 1788 N ↑')+text(280,350,'Weight 588 N ↓')+arrow(610,270,610,150,'#2a6bb2')+text(470,120,'Resultant 1200 N ↑')+text(440,310,'Not an extra force')+text(80,430,'1788 − 588 = 1200 N; Δp/Δt gives net, not ground force.');
return svg('Worked '+kind+' scenario with explicitly labelled force or impulse relationships',b,kind==='pulley'||kind==='graph'?510:480);}


const s0={"id": "y11-newton-focus-2", "parent": "y11-newton", "title": "Action and reaction: who pushes whom?", "shortTitle": "Action and reaction", "subtitle": "Both skaters accelerate even though neither pushes against the ground. Identify the interaction first: each skater pushes on the other.", "pages": [{"chapter": 0, "title": "Two skaters push apart", "html": "__DIAGRAM__<div class=\"pp-page\"><p>Both skaters accelerate even though neither pushes against the ground. Identify the interaction first: each skater pushes on the other.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Name the receiving object", "html": "<div class=\"pp-page\"><p>Write force ON A BY B. This order prevents you from putting a force acting on B into A’s equation.</p></div>", "type": "learn"}, {"chapter": 0, "title": "One diagram for one object", "html": "<div class=\"pp-page\"><p>A free-body diagram contains only forces acting on the selected object. The force that object exerts on another belongs on the other diagram.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Third-law pair", "html": "<div class=\"pp-page\"><p>F on A by B = −F on B by A. These forces have equal magnitude, opposite direction, the same interaction type, and different receiving objects.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Equal forces do not cancel on one object", "html": "<div class=\"pp-page\"><p>Cancellation requires adding forces acting on the same object. The skaters’ mutual forces act on different skaters.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Simultaneous interaction", "html": "<div class=\"pp-page\"><p>There is no first push and delayed reaction in the classical model. Both interaction forces exist together throughout contact.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Weight and normal are not a third-law pair", "html": "<div class=\"pp-page\"><p>Both act on the same person. The partner of Earth pulling the person is the person pulling Earth; the partner of the floor pushing the person is the person pushing the floor.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Contact and noncontact pairs", "html": "<div class=\"pp-page\"><p>A rope pulls a cart while the cart pulls the rope. Earth attracts a ball while the ball attracts Earth. Contact is not required for Newton’s third law.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Compare acceleration rather than force", "html": "<div class=\"pp-page\"><p>For an isolated horizontal push, a = F/m. Equal interaction forces can cause unequal acceleration magnitudes because masses differ.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Large truck and small car", "html": "<div class=\"pp-page\"><p>During a collision, their mutual contact-force magnitudes are equal. The smaller mass can have a larger acceleration; damage also depends on deformation and structure.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Earth’s small acceleration", "html": "<div class=\"pp-page\"><p>A falling ball pulls Earth with the same force as Earth pulls the ball. Earth’s much larger mass makes its acceleration extraordinarily small.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Net force is a sum", "html": "<div class=\"pp-page\"><p>A contact pair tells you one interaction. Acceleration depends on the vector sum of all external forces on the chosen body.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Balanced forces can coexist with interaction", "html": "<div class=\"pp-page\"><p>A book at rest feels upward support and downward weight. It still pushes the table down. Rest does not mean no forces.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Choose horizontal signs", "html": "<div class=\"pp-page\"><p>Take right positive. A leftward force is negative. Write the signed sum before dividing by mass.</p></div>", "type": "learn"}, {"chapter": 1, "title": "A pull at constant speed", "html": "__DETAIL__<div class=\"pp-page\"><p>If a cart travels straight at constant speed, acceleration is zero. The forward pull balances resistance; it is not larger than resistance.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Speed and acceleration are different", "html": "<div class=\"pp-page\"><p>An object moving right can accelerate left while slowing. A force arrow does not automatically point along velocity.</p></div>", "type": "learn"}, {"chapter": 1, "title": "System boundary changes the force list", "html": "<div class=\"pp-page\"><p>For two carts together, their mutual contact force is internal and cancels in the whole-system sum. For either cart alone, it is external.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Internal cancellation is legitimate", "html": "<div class=\"pp-page\"><p>The pair cancels in the system total because both receiving objects are now inside the boundary. It never cancels in either individual equation.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Pushing two carts", "html": "<div class=\"pp-page\"><p>First use total mass to find shared acceleration; then isolate the unpushed cart to find the contact force needed to accelerate it.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Swap which cart you push", "html": "<div class=\"pp-page\"><p>The same external push gives the same system acceleration. The internal contact force changes because it must accelerate a different trailing mass.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Rope model", "html": "<div class=\"pp-page\"><p>A massless rope transmits equal tension when otherwise ideal. A rope with appreciable mass can require unequal end forces to accelerate itself.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Do not count acceleration as a force", "html": "<div class=\"pp-page\"><p>ma is the resulting net force, not an additional arrow alongside the real forces. Adding it twice produces a false equation.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Predict before calculating", "html": "<div class=\"pp-page\"><p>Ask whether doubling one mass changes the interaction or just its response. If the mutual force is specified unchanged, acceleration halves.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Explain a claim precisely", "html": "<div class=\"pp-page\"><p>“The stronger skater pushes harder” is incomplete. During their mutual interaction, the pair magnitudes remain equal; different net forces may come from other interactions.</p></div>", "type": "learn"}, {"chapter": 2, "title": "Worked scenario: Skaters with unequal masses", "html": "__WORKED_DIAGRAM__<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 40.0 kg skater and an 80.0 kg skater interact with a 120 N horizontal force for 0.500 s. Start at rest; neglect resistance.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Skaters with unequal masses", "html": "<div class=\"pp-page\"><p>For the lighter skater choose right positive: a = 120/40 = +3.00 m/s². For the heavier skater, a = −120/80 = −1.50 m/s². Multiply each by 0.500 s: velocities +1.50 and −0.750 m/s. Their final momenta +60.0 and −60.0 kg·m/s cancel. Equal forces produced unequal acceleration.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Two carts in contact", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 30.0 N force pushes a 2.00 kg cart into a 3.00 kg cart on a frictionless track. Find acceleration and contact force.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Two carts in contact", "html": "<div class=\"pp-page\"><p>Whole system: a = 30.0/(2.00 + 3.00) = 6.00 m/s². Isolate the 3.00 kg cart: its only horizontal force is contact, so Fcontact = 3.00 × 6.00 = 18.0 N. The 2.00 kg cart receives 30.0 N forward and 18.0 N backward, leaving 12.0 N = 2.00 × 6.00. If the 3 kg cart were pushed into the 2 kg cart instead, contact would be 12.0 N.</p></div>", "type": "worked"}, {"chapter": 3, "title": "Guided reasoning: identify the model", "html": "__CHECK__", "type": "practice"}, {"chapter": 3, "title": "Guided calculation: one step at a time", "html": "__NUMBER__", "type": "practice"}, {"chapter": 3, "title": "Independent: A 50 kg and a 75 kg skater push with mutual force 150 N for 0.", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 0}, {"chapter": 3, "title": "Independent: A 20 N push acts on a 1 kg cart that pushes a 4 kg cart on a f", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 1}, {"chapter": 3, "title": "Explain the limit of your answer", "html": "<div class=\"pp-page\"><p>“The stronger skater pushes harder” is incomplete. During their mutual interaction, the pair magnitudes remain equal; different net forces may come from other interactions.</p><p>Write a short explanation tied to one worked example: name an assumption, explain which equation uses it, and describe a physical change that would require a new model. Keep force, impulse and velocity directions explicit.</p>__PAPER__</div>", "type": "practice"}], "bank": [{"q": "Third-law forces act on…", "o": ["different objects", "one object", "only stationary objects"], "a": 0, "explain": "Different receiving objects are essential."}, {"q": "A truck hits a car. Mutual contact forces are…", "o": ["equal in magnitude", "larger on the car", "zero on the truck"], "a": 0, "explain": "Their accelerations can differ, but the contact pair magnitudes are equal."}, {"q": "Weight and normal on a book are…", "o": ["not a third-law pair", "always a third-law pair", "the same interaction"], "a": 0, "explain": "Both act on the book."}, {"q": "For fixed force, doubling mass makes acceleration…", "o": ["half", "double", "unchanged"], "a": 0, "explain": "a = F/m."}, {"q": "Constant straight-line speed implies…", "o": ["zero net force", "zero forces", "positive net force"], "a": 0, "explain": "The vector sum is zero, even with forces present."}, {"q": "Internal forces cancel in…", "o": ["whole-system sums", "every individual diagram", "only gravity problems"], "a": 0, "explain": "Both members of the pair must be inside the boundary."}], "practice": [{"q": "A 50 kg and a 75 kg skater push with mutual force 150 N for 0.20 s from rest. Find both accelerations and speeds.", "points": ["Equal mutual-force magnitudes: 150 N, opposite directions.", "50 kg acceleration magnitude = 150/50 = 3.00 m/s².", "75 kg acceleration magnitude = 150/75 = 2.00 m/s².", "Speeds = at: 0.600 and 0.400 m/s, opposite directions."]}, {"q": "A 20 N push acts on a 1 kg cart that pushes a 4 kg cart on a frictionless track. Calculate acceleration and contact force.", "points": ["System mass = 5 kg; a = 20/5 = 4 m/s².", "Isolate the 4 kg cart.", "Contact force = 4 × 4 = 16 N.", "Opposite 16 N acts on 1 kg cart; its net force is 4 N."]}], "chapters": [["Recognise", "Identify objects, signs and regimes"], ["Build", "Construct the model and its limits"], ["Solve", "Follow explained original exam-style examples"], ["Practise", "Reason, calculate and transfer"]], "constants": "Use g = 9.80 m/s². Use SI units and stated idealisations. Practice questions are original exam-style teaching questions.", "summary": "Both skaters accelerate even though neither pushes against the ground. Identify the interaction first: each skater pushes on the other.", "focus": {"question": "A 50 kg and a 75 kg skater push with mutual force 150 N for 0.20 s from rest. Find both accelerations and speeds.", "points": ["Equal mutual-force magnitudes: 150 N, opposite directions.", "50 kg acceleration magnitude = 150/50 = 3.00 m/s².", "75 kg acceleration magnitude = 150/75 = 2.00 m/s².", "Speeds = at: 0.600 and 0.400 m/s, opposite directions."], "claim": "one object"}};
s0.pages.forEach(p=>{p.html=p.html.replace('__DIAGRAM__',diagram('pair')).replace('__DETAIL__',detail('pair')).replace('__WORKED_DIAGRAM__',workedDiagram('pair')).replace('__CHECK__',check('y11-newton-focus-2-guided',"A truck hits a car. Mutual contact forces are\u2026",["equal in magnitude", "larger on the car", "zero on the truck"],0,["Their accelerations can differ, but the contact pair magnitudes are equal.", "Their accelerations can differ, but the contact pair magnitudes are equal.", "Their accelerations can differ, but the contact pair magnitudes are equal."])).replace('__NUMBER__',number('y11-newton-focus-2-numeric',"Find the acceleration magnitude of a 60 kg skater under 180 N.",3,"m/s\u00b2","a = F/m = 180/60 = 3 m/s\u00b2.",.02)).replace('__PAPER__',paper('Explain a model assumption'));if(p.html==='__PRACTICE__'){const x=s0.practice[p.practiceIndex];p.html='<div class="pp-page">'+P('<b>Original exam-style · '+x.points.length+' marks.</b> '+x.q)+paper('Your diagram, reasoning and calculations')+R('Explain the marking points',mark(x.points))+'</div>';}});C.register(s0);
const s1={"id": "y11-newton-focus-3", "parent": "y11-newton", "title": "Lifts and tension: what does a scale measure?", "shortTitle": "Lifts and tension", "subtitle": "The passenger’s mass stays constant. The changing contact force from the floor changes the sensation and scale reading.", "pages": [{"chapter": 0, "title": "Feeling heavier in a lift", "html": "__DIAGRAM__<div class=\"pp-page\"><p>The passenger’s mass stays constant. The changing contact force from the floor changes the sensation and scale reading.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Isolate the passenger", "html": "<div class=\"pp-page\"><p>Include normal force N upward and weight mg downward. Do not put cable tension on this diagram: the cable pulls the lift, not the passenger directly.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Choose up positive", "html": "<div class=\"pp-page\"><p>N − mg = ma. The acceleration a is signed relative to up. Weight magnitude mg remains positive in this notation.</p></div>", "type": "learn"}, {"chapter": 0, "title": "What the scale measures", "html": "<div class=\"pp-page\"><p>A force scale measures normal contact force. A scale displaying kilograms divides that force by its calibration value of g; it does not directly detect mass changes.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Actual weight", "html": "<div class=\"pp-page\"><p>Weight is the gravitational force mg. “Apparent weight” refers to the support-force reading, so distinguish the two in explanations.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Upward acceleration", "html": "<div class=\"pp-page\"><p>For a > 0, N = m(g + a), so the scale reading exceeds mg. This happens both while starting upward and slowing downward.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Downward acceleration", "html": "<div class=\"pp-page\"><p>For a < 0, N = m(g − |a|), so the reading is below mg. This happens while starting downward or slowing upward.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Moving upward is insufficient", "html": "<div class=\"pp-page\"><p>Velocity alone does not tell you the scale reading. An upward-moving lift may accelerate up, accelerate down, or have zero acceleration.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Constant speed", "html": "<div class=\"pp-page\"><p>With no acceleration, N = mg whether the lift moves up or down. A moving scale can show the same value as a stationary one.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Find acceleration from velocity change", "html": "<div class=\"pp-page\"><p>Use a = (v − u)/t with up-positive velocities. A decrease from +4 to +1 m/s gives negative acceleration.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Free-fall idealisation", "html": "<div class=\"pp-page\"><p>At a = −g, N = 0. Passenger and lift fall together without contact compression. Gravity still acts; zero scale reading is not zero gravity.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Contact cannot pull", "html": "<div class=\"pp-page\"><p>For an unsupported person standing on the floor, N cannot be negative. A result N < 0 means the assumed floor-contact model is invalid.</p></div>", "type": "learn"}, {"chapter": 1, "title": "A hanging object", "html": "<div class=\"pp-page\"><p>Replace support N with rope tension T: T − mg = ma. Tension pulls along the rope and cannot push.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Cable tension of the whole lift", "html": "<div class=\"pp-page\"><p>For total moving mass M, external forces are cable tension upward and total weight downward. T − Mg = Ma.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Do not mix the masses", "html": "__DETAIL__<div class=\"pp-page\"><p>Passenger mass belongs in N − mg = ma. Lift-plus-passenger mass belongs in the cable-tension equation.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Mass shown in kilograms", "html": "<div class=\"pp-page\"><p>Displayed value mdisplay = N/9.80 under standard calibration. A 588 N reading corresponds to 60.0 displayed kg.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Inverse problem", "html": "<div class=\"pp-page\"><p>If N and m are known, solve a = N/m − g. Check the sign before explaining the movement.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Two supports on one passenger", "html": "<div class=\"pp-page\"><p>If two vertical supports share load, their normal forces add. Their individual values need additional information about geometry or loading.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Smooth turning points", "html": "<div class=\"pp-page\"><p>At the instant velocity is zero, acceleration need not be zero. A lift can momentarily stop while its scale reading remains changed.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Direction from a story", "html": "<div class=\"pp-page\"><p>“Descending and slowing” means downward velocity becomes less negative, hence acceleration is upward and N > mg.</p></div>", "type": "learn"}, {"chapter": 1, "title": "A spring balance in a lift", "html": "<div class=\"pp-page\"><p>A hanging spring balance reads tension, which follows the same signed acceleration relationship as floor support.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Measurement limits", "html": "<div class=\"pp-page\"><p>A real scale may lag or oscillate during a sudden change. The ideal calculation describes the support force during the stated constant-acceleration interval.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Elevator and person as system", "html": "<div class=\"pp-page\"><p>The force between floor and passenger becomes internal; it is omitted from the external cable-force equation.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Avoid fictitious force arrows", "html": "<div class=\"pp-page\"><p>Use an inertial ground frame here. Acceleration is explained by unequal real forces. Accelerating-frame pseudo-forces are an optional extension, not needed for these solutions.</p></div>", "type": "learn"}, {"chapter": 2, "title": "Worked scenario: Passenger descending but slowing", "html": "__WORKED_DIAGRAM__<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 60.0 kg passenger moves downward at 4.00 m/s, slowing to 1.00 m/s in 2.00 s. Find scale force.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Passenger descending but slowing", "html": "<div class=\"pp-page\"><p>Up positive: u = −4.00, v = −1.00 m/s. a = [−1 − (−4)]/2 = +1.50 m/s². N = 60.0(9.80 + 1.50) = 678 N. The scale is above the resting 588 N because acceleration is upward although motion remains downward.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Find acceleration from the scale", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 50.0 kg passenger experiences a scale force 390 N. Find acceleration and cable tension if total lift-plus-passenger mass is 800 kg.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Find acceleration from the scale", "html": "<div class=\"pp-page\"><p>a = 390/50.0 − 9.80 = −2.00 m/s², downward. This does not determine velocity direction. Whole lift: T = 800(9.80 − 2.00) = 6240 N. Do not use 390 N as the cable force; it is the local passenger support.</p></div>", "type": "worked"}, {"chapter": 3, "title": "Guided reasoning: identify the model", "html": "__CHECK__", "type": "practice"}, {"chapter": 3, "title": "Guided calculation: one step at a time", "html": "__NUMBER__", "type": "practice"}, {"chapter": 3, "title": "Independent: A 70 kg passenger accelerates down at 1.20 m/s². Find normal f", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 0}, {"chapter": 3, "title": "Independent: A lift of total mass 1000 kg slows from upward 3 m/s to rest i", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 1}, {"chapter": 3, "title": "Explain the limit of your answer", "html": "<div class=\"pp-page\"><p>Use an inertial ground frame here. Acceleration is explained by unequal real forces. Accelerating-frame pseudo-forces are an optional extension, not needed for these solutions.</p><p>Write a short explanation tied to one worked example: name an assumption, explain which equation uses it, and describe a physical change that would require a new model. Keep force, impulse and velocity directions explicit.</p>__PAPER__</div>", "type": "practice"}], "bank": [{"q": "Descending and slowing gives scale force…", "o": ["greater than mg", "less than mg", "zero"], "a": 0, "explain": "The acceleration is upward."}, {"q": "At constant downward speed N equals…", "o": ["mg", "zero", "2mg"], "a": 0, "explain": "Acceleration is zero."}, {"q": "A negative predicted N means…", "o": ["contact assumption fails", "negative mass", "upward gravity"], "a": 0, "explain": "The floor cannot pull the passenger down."}, {"q": "Cable force equation uses…", "o": ["total supported moving mass", "only passenger mass", "no mass"], "a": 0, "explain": "Include the lift and its load."}, {"q": "At v = 0 acceleration…", "o": ["may be nonzero", "must be zero", "must equal g"], "a": 0, "explain": "Velocity and acceleration are different quantities."}, {"q": "In free fall the passenger has…", "o": ["weight but zero support", "no gravitational force", "infinite support"], "a": 0, "explain": "a = −g gives N = 0."}], "practice": [{"q": "A 70 kg passenger accelerates down at 1.20 m/s². Find normal force and displayed kg.", "points": ["Up positive: a = −1.20 m/s².", "N = 70(9.80 − 1.20) = 602 N.", "Displayed kg = 602/9.80 = 61.4 kg.", "Actual mass remains 70 kg."]}, {"q": "A lift of total mass 1000 kg slows from upward 3 m/s to rest in 2 s. Calculate cable tension.", "points": ["a = (0 − 3)/2 = −1.5 m/s².", "T − Mg = Ma.", "T = 1000(9.80 − 1.50) = 8300 N.", "T below weight is consistent with downward acceleration."]}], "chapters": [["Recognise", "Identify objects, signs and regimes"], ["Build", "Construct the model and its limits"], ["Solve", "Follow explained original exam-style examples"], ["Practise", "Reason, calculate and transfer"]], "constants": "Use g = 9.80 m/s². Use SI units and stated idealisations. Practice questions are original exam-style teaching questions.", "summary": "The passenger’s mass stays constant. The changing contact force from the floor changes the sensation and scale reading.", "focus": {"question": "A 70 kg passenger accelerates down at 1.20 m/s². Find normal force and displayed kg.", "points": ["Up positive: a = −1.20 m/s².", "N = 70(9.80 − 1.20) = 602 N.", "Displayed kg = 602/9.80 = 61.4 kg.", "Actual mass remains 70 kg."], "claim": "less than mg"}};
s1.pages.forEach(p=>{p.html=p.html.replace('__DIAGRAM__',diagram('lift')).replace('__DETAIL__',detail('lift')).replace('__WORKED_DIAGRAM__',workedDiagram('lift')).replace('__CHECK__',check('y11-newton-focus-3-guided',"At constant downward speed N equals\u2026",["mg", "zero", "2mg"],0,["Acceleration is zero.", "Acceleration is zero.", "Acceleration is zero."])).replace('__NUMBER__',number('y11-newton-focus-3-numeric',"A 50 kg passenger accelerates upward at 2 m/s\u00b2. Find support force.",590,"N","N = m(g + a) = 50(9.8 + 2) = 590 N.",.02)).replace('__PAPER__',paper('Explain a model assumption'));if(p.html==='__PRACTICE__'){const x=s1.practice[p.practiceIndex];p.html='<div class="pp-page">'+P('<b>Original exam-style · '+x.points.length+' marks.</b> '+x.q)+paper('Your diagram, reasoning and calculations')+R('Explain the marking points',mark(x.points))+'</div>';}});C.register(s1);
const s2={"id": "y11-friction-slopes-focus-1", "parent": "y11-friction-slopes", "title": "Horizontal friction: sticking, pulling and pushing", "shortTitle": "Horizontal friction", "subtitle": "Static friction adjusts to balance the horizontal push while contact remains stuck. It is not automatically its maximum value.", "pages": [{"chapter": 0, "title": "Why a small push does not move a crate", "html": "__DIAGRAM__<div class=\"pp-page\"><p>Static friction adjusts to balance the horizontal push while contact remains stuck. It is not automatically its maximum value.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Identify contact and motion", "html": "<div class=\"pp-page\"><p>Ask whether the surfaces slip relative to each other. Static means no relative sliding at that contact; kinetic means sliding.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Static bound", "html": "<div class=\"pp-page\"><p>0 ≤ fs ≤ μsN. Equality only at the limiting threshold. Using μsN for every resting situation overestimates friction.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Kinetic model", "html": "<div class=\"pp-page\"><p>During sliding, fk = μkN in this simple model. μ is dimensionless; friction has units newtons.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Friction direction", "html": "<div class=\"pp-page\"><p>Friction opposes relative slipping or its tendency, not necessarily the object’s velocity relative to the ground.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Level horizontal pull", "html": "<div class=\"pp-page\"><p>With a purely horizontal pull and zero vertical acceleration, N = mg. Net horizontal force is pull minus opposing friction.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Vertical balance first", "html": "<div class=\"pp-page\"><p>Determine N before calculating friction. Extra vertical components change contact load even on level ground.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Pull at an angle", "html": "<div class=\"pp-page\"><p>For pull F at θ above horizontal, Fx = F cosθ and Fy = F sinθ. Upward Fy reduces N: N = mg − F sinθ.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Push at an angle", "html": "<div class=\"pp-page\"><p>For a push angled downward, N = mg + F sinθ. The downward component increases contact load and modelled friction.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Check contact remains", "html": "<div class=\"pp-page\"><p>For angled pull, N ≥ 0 is required. If the upward component exceeds weight, lift-off occurs and the sliding-contact model is invalid.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Find the static threshold", "html": "<div class=\"pp-page\"><p>At impending rightward slip: F cosθ = μs(mg − F sinθ). Solve F(cosθ + μs sinθ) = μsmg.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Threshold for downward push", "html": "<div class=\"pp-page\"><p>F cosθ = μs(mg + F sinθ). The plus vertical load becomes a minus in the rearranged denominator: F = μsmg/(cosθ − μs sinθ), if denominator is positive.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Coefficient is not a force", "html": "<div class=\"pp-page\"><p>A μ = 0.30 coefficient says friction magnitude is 30% of N in the kinetic model, not 0.30 N.</p></div>", "type": "learn"}, {"chapter": 1, "title": "At rest with 10 N pull", "html": "<div class=\"pp-page\"><p>If maximum static friction is 20 N and no other horizontal force acts, actual friction is 10 N opposite the pull.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Just after motion starts", "html": "__DETAIL__<div class=\"pp-page\"><p>The applicable coefficient changes from static to kinetic. Often μk < μs, so the same applied force creates a positive net force once sliding begins.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Already sliding and weak pull", "html": "<div class=\"pp-page\"><p>A forward pull smaller than kinetic friction gives acceleration backward. The object can still move forward while slowing.</p></div>", "type": "learn"}, {"chapter": 1, "title": "What happens at the stop", "html": "<div class=\"pp-page\"><p>Do not extend constant backward kinetic friction beyond zero speed without checking the next contact state. Static friction may then hold the object.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Find coefficient experimentally", "html": "<div class=\"pp-page\"><p>At steady sliding speed on a level surface with horizontal pull, μk = Fpull/(mg). Constant speed is the condition making pull equal friction.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Angled experimental pull", "html": "<div class=\"pp-page\"><p>At steady speed with upward angled pull, use μk = F cosθ/(mg − F sinθ), not F/(mg).</p></div>", "type": "learn"}, {"chapter": 1, "title": "No-force sliding coast", "html": "<div class=\"pp-page\"><p>With no applied horizontal force, a = −μkg while sliding on a level surface. Mass cancels in this ideal model.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Surface dependence", "html": "<div class=\"pp-page\"><p>Coefficients describe a particular material pair and conditions. Moisture, contamination and wear can change real behaviour.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Traction is often static friction", "html": "<div class=\"pp-page\"><p>A rolling wheel without slipping can be driven forward by static friction. “Friction always slows objects” is too broad.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Predict pull versus push", "html": "<div class=\"pp-page\"><p>For equal F and angle, pulling up gives smaller N and smaller kinetic resistance than pushing down, if both remain in contact.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Separate model from measurement", "html": "<div class=\"pp-page\"><p>The simple coefficient model approximates complex contact. If measured friction depends on speed, explain that this exceeds its constant-μ assumptions.</p></div>", "type": "learn"}, {"chapter": 2, "title": "Worked scenario: Sticking then sliding", "html": "__WORKED_DIAGRAM__<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 10.0 kg crate has μs = 0.40 and μk = 0.30. A horizontal 30 N push acts from rest, then increases to 50 N.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Sticking then sliding", "html": "<div class=\"pp-page\"><p>N = 98.0 N. Static maximum = 0.40 × 98.0 = 39.2 N. At 30 N actual friction is 30 N and a = 0. At 50 N the static bound is exceeded. Sliding friction = 29.4 N and a = (50.0 − 29.4)/10.0 = 2.06 m/s². State the contact regime before selecting the coefficient.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Angled pull on sliding crate", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 10.0 kg crate slides right under a 50.0 N pull at 30.0° above horizontal; μk = 0.20.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Angled pull on sliding crate", "html": "<div class=\"pp-page\"><p>Fx = 50 cos30° = 43.301 N; Fy = 25.0 N. Vertical balance gives N = 98.0 − 25.0 = 73.0 N. fk = 0.20 × 73.0 = 14.6 N. a = (43.301 − 14.6)/10.0 = 2.87 m/s² right. If pushed downward at the same angle, N = 123 N and a = 1.87 m/s².</p></div>", "type": "worked"}, {"chapter": 3, "title": "Guided reasoning: identify the model", "html": "__CHECK__", "type": "practice"}, {"chapter": 3, "title": "Guided calculation: one step at a time", "html": "__NUMBER__", "type": "practice"}, {"chapter": 3, "title": "Independent: A resting 5 kg box with μs = 0.50 receives a 15 N horizontal p", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 0}, {"chapter": 3, "title": "Independent: An 8 kg box slides under 40 N at 30° downward; μk = 0.25. Calc", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 1}, {"chapter": 3, "title": "Explain the limit of your answer", "html": "<div class=\"pp-page\"><p>The simple coefficient model approximates complex contact. If measured friction depends on speed, explain that this exceeds its constant-μ assumptions.</p><p>Write a short explanation tied to one worked example: name an assumption, explain which equation uses it, and describe a physical change that would require a new model. Keep force, impulse and velocity directions explicit.</p>__PAPER__</div>", "type": "practice"}], "bank": [{"q": "Static friction at rest is…", "o": ["adjustable up to a bound", "always μsN", "always zero"], "a": 0, "explain": "It balances the required tangential force while possible."}, {"q": "Upward angled pulling makes N…", "o": ["smaller than mg", "larger than mg", "always zero"], "a": 0, "explain": "The upward component shares the weight support."}, {"q": "Kinetic coefficient has units…", "o": ["none", "newtons", "kg"], "a": 0, "explain": "It is a force ratio."}, {"q": "Forward motion with backward net force…", "o": ["slows initially", "is impossible", "must reverse instantly"], "a": 0, "explain": "Velocity changes continuously."}, {"q": "After sliding stops…", "o": ["reassess static contact", "keep kinetic force forever", "delete gravity"], "a": 0, "explain": "The contact regime can change."}, {"q": "A driven wheel’s static friction can point…", "o": ["forward", "only backward", "only down"], "a": 0, "explain": "Friction opposes slipping tendency at contact."}], "practice": [{"q": "A resting 5 kg box with μs = 0.50 receives a 15 N horizontal push. Find N, static maximum and actual friction.", "points": ["N = 49.0 N.", "Maximum = 24.5 N.", "15 N is within the bound, so actual static friction = 15 N opposite push.", "a = 0."]}, {"q": "An 8 kg box slides under 40 N at 30° downward; μk = 0.25. Calculate acceleration.", "points": ["Fx = 40 cos30° = 34.64 N.", "N = 8(9.8) + 40 sin30° = 98.4 N.", "fk = 24.6 N.", "a = (34.64 − 24.6)/8 = 1.26 m/s² forward."]}], "chapters": [["Recognise", "Identify objects, signs and regimes"], ["Build", "Construct the model and its limits"], ["Solve", "Follow explained original exam-style examples"], ["Practise", "Reason, calculate and transfer"]], "constants": "Use g = 9.80 m/s². Use SI units and stated idealisations. Practice questions are original exam-style teaching questions.", "summary": "Static friction adjusts to balance the horizontal push while contact remains stuck. It is not automatically its maximum value.", "focus": {"question": "A resting 5 kg box with μs = 0.50 receives a 15 N horizontal push. Find N, static maximum and actual friction.", "points": ["N = 49.0 N.", "Maximum = 24.5 N.", "15 N is within the bound, so actual static friction = 15 N opposite push.", "a = 0."], "claim": "always μsN"}};
s2.pages.forEach(p=>{p.html=p.html.replace('__DIAGRAM__',diagram('friction')).replace('__DETAIL__',detail('friction')).replace('__WORKED_DIAGRAM__',workedDiagram('friction')).replace('__CHECK__',check('y11-friction-slopes-focus-1-guided',"Upward angled pulling makes N\u2026",["smaller than mg", "larger than mg", "always zero"],0,["The upward component shares the weight support.", "The upward component shares the weight support.", "The upward component shares the weight support."])).replace('__NUMBER__',number('y11-friction-slopes-focus-1-numeric',"A 5 kg box slides under a horizontal pull. \u03bck = 0.2. Find kinetic friction.",9.8,"N","N = mg = 49 N, then fk = 0.2 \u00d7 49 = 9.8 N.",.02)).replace('__PAPER__',paper('Explain a model assumption'));if(p.html==='__PRACTICE__'){const x=s2.practice[p.practiceIndex];p.html='<div class="pp-page">'+P('<b>Original exam-style · '+x.points.length+' marks.</b> '+x.q)+paper('Your diagram, reasoning and calculations')+R('Explain the marking points',mark(x.points))+'</div>';}});C.register(s2);
const s3={"id": "y11-friction-slopes-focus-3", "parent": "y11-friction-slopes", "title": "Connected masses: ropes, pulleys and limiting motion", "shortTitle": "Connected masses", "subtitle": "A taut inextensible rope around a fixed ideal pulley makes the attached masses travel equal distances along their paths.", "pages": [{"chapter": 0, "title": "One rope links two motions", "html": "__DIAGRAM__<div class=\"pp-page\"><p>A taut inextensible rope around a fixed ideal pulley makes the attached masses travel equal distances along their paths.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Shared acceleration magnitude", "html": "<div class=\"pp-page\"><p>One mass moves horizontally while another moves vertically, so acceleration vectors differ in direction although their path magnitudes match.</p></div>", "type": "learn"}, {"chapter": 0, "title": "The ideal rope", "html": "<div class=\"pp-page\"><p>Neglect rope mass and stretching. Under this assumption one tension magnitude applies throughout the same rope.</p></div>", "type": "learn"}, {"chapter": 0, "title": "The ideal pulley", "html": "<div class=\"pp-page\"><p>Neglect axle friction and pulley rotational inertia. Real pulleys can require different tensions on their two sides.</p></div>", "type": "learn"}, {"chapter": 0, "title": "A hanging mass does not have T = mg automatically", "html": "<div class=\"pp-page\"><p>If it accelerates downward, mg − T = ma, so T < mg. Balance only holds when acceleration is zero.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Draw each mass separately", "html": "<div class=\"pp-page\"><p>A table block feels N, mg, tension and possibly friction. The hanging mass feels only weight and tension in the simple model.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Choose compatible positive directions", "html": "<div class=\"pp-page\"><p>Table-right and hanging-down can both be positive along the rope’s assumed motion. These are path coordinates, not a single global vector direction.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Smooth table equation", "html": "<div class=\"pp-page\"><p>For mass m1 on a frictionless table, T = m1a. For hanging m2: m2g − T = m2a.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Add the equations", "html": "<div class=\"pp-page\"><p>T cancels algebraically and a = m2g/(m1 + m2). The driving force accelerates both masses.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Recover tension afterwards", "html": "<div class=\"pp-page\"><p>Use T = m1a or T = m2(g − a). Agreement checks arithmetic and signs.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Why a is less than g", "html": "<div class=\"pp-page\"><p>For nonzero table mass, a = g m2/(m1 + m2) < g. The rope must also accelerate the table block.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Rough table", "html": "<div class=\"pp-page\"><p>If sliding right, friction fk = μkm1g acts left. The system driving force is m2g − fk.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Rough table acceleration", "html": "<div class=\"pp-page\"><p>a = (m2g − μkm1g)/(m1 + m2), for the assumed right/down sliding state. A negative value can mean deceleration of existing motion.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Start from rest: check static friction", "html": "<div class=\"pp-page\"><p>For a resting system, required table friction is m2g. It can remain stationary if m2g ≤ μsm1g.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Limiting hanging mass", "html": "__DETAIL__<div class=\"pp-page\"><p>At impending right/down movement, m2 = μsm1. This criterion relies on horizontal table and vertical hanging string geometry.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Atwood arrangement", "html": "<div class=\"pp-page\"><p>Two hanging masses on either side give (mheavy − mlight)g = (mheavy + mlight)a, with heavy-down positive.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Light mass equation", "html": "<div class=\"pp-page\"><p>For the lighter mass moving up, T − mlightg = mlighta. Its tension exceeds its weight.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Heavy mass equation", "html": "<div class=\"pp-page\"><p>For the heavier mass moving down, mheavyg − T = mheavya. Its tension is below its weight.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Equal hanging masses", "html": "<div class=\"pp-page\"><p>Ideal equal masses give a = 0. They may remain still or travel at constant speed if already moving.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Tension is not the net system drive", "html": "<div class=\"pp-page\"><p>The system drive comes from unmatched external path-directed weights and resistance. Do not set T equal to the sum of all weights.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Rope slack condition", "html": "<div class=\"pp-page\"><p>A rope cannot push. A calculated negative tension means the assumed taut-rope solution does not apply.</p></div>", "type": "learn"}, {"chapter": 1, "title": "A mass hits the floor", "html": "<div class=\"pp-page\"><p>The connected-stage model ends at impact. The rope may slacken; analyse subsequent block motion with a new force list.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Use kinematics only for the valid stage", "html": "<div class=\"pp-page\"><p>With constant a and initial rest, v² = 2as and t = sqrt(2s/a). Use the hanging clearance as the available distance.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Extension: inclined connected block", "html": "<div class=\"pp-page\"><p>Resolving mg along and perpendicular to an incline extends the same method. Check syllabus/teacher expectations before treating complex pulley geometry as required.</p></div>", "type": "learn"}, {"chapter": 2, "title": "Worked scenario: Smooth table and hanging mass", "html": "__WORKED_DIAGRAM__<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 3 kg table block is joined to a 2 kg hanging mass. Start at rest on an ideal system.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Smooth table and hanging mass", "html": "<div class=\"pp-page\"><p>T = 3a; 19.6 − T = 2a. Add: 19.6 = 5a, giving a = 3.92 m/s². Then T = 11.76 N. If the hanging mass descends 0.50 m before contact with the floor, v = sqrt(2 × 3.92 × 0.50) = 1.98 m/s. Stop using this linked-force model at impact.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Rough table: decide whether it moves", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 4 kg table block has μs = 0.30 and μk = 0.20; the hanging mass is 2 kg.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Rough table: decide whether it moves", "html": "<div class=\"pp-page\"><p>N = 39.2 N. Maximum static friction = 11.76 N, smaller than hanging weight 19.6 N, so it cannot stay at rest. Sliding friction = 7.84 N. a = (19.6 − 7.84)/6 = 1.96 m/s². T = 4a + 7.84 = 15.68 N; hanging check: 19.6 − 15.68 = 2 × 1.96.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Two hanging masses", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> An ideal pulley connects masses 5 kg and 3 kg. Find a and T.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Two hanging masses", "html": "<div class=\"pp-page\"><p>Take 5 kg down and 3 kg up positive along paths. a = (5 − 3)9.8/(5 + 3) = 2.45 m/s². T = 3(9.8 + 2.45) = 36.75 N, also 5(9.8 − 2.45). T lies between the two weights.</p></div>", "type": "worked"}, {"chapter": 3, "title": "Guided reasoning: identify the model", "html": "__CHECK__", "type": "practice"}, {"chapter": 3, "title": "Guided calculation: one step at a time", "html": "__NUMBER__", "type": "practice"}, {"chapter": 3, "title": "Independent: A smooth table block of 6 kg joins a 2 kg hanging mass. Find a", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 0}, {"chapter": 3, "title": "Independent: A 5 kg rough-table block with μs = 0.4 joins a 1.5 kg hanging ", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 1}, {"chapter": 3, "title": "Explain the limit of your answer", "html": "<div class=\"pp-page\"><p>Resolving mg along and perpendicular to an incline extends the same method. Check syllabus/teacher expectations before treating complex pulley geometry as required.</p><p>Write a short explanation tied to one worked example: name an assumption, explain which equation uses it, and describe a physical change that would require a new model. Keep force, impulse and velocity directions explicit.</p>__PAPER__</div>", "type": "practice"}], "bank": [{"q": "A taut ideal rope implies equal…", "o": ["path acceleration magnitudes", "masses", "weight forces"], "a": 0, "explain": "The rope length constraint couples motion."}, {"q": "Hanging mass accelerates down, so T…", "o": ["is below mg", "equals mg", "exceeds mg"], "a": 0, "explain": "mg − T = ma > 0."}, {"q": "Static system first needs…", "o": ["friction-bound test", "kinetic friction automatically", "a = g"], "a": 0, "explain": "Check whether static contact can hold."}, {"q": "Equal ideal hanging masses give…", "o": ["a = 0", "a = g", "zero tension"], "a": 0, "explain": "The driving weight difference vanishes."}, {"q": "At floor impact the previous model…", "o": ["must be reassessed", "continues forever", "loses all gravity"], "a": 0, "explain": "The rope constraint/contact situation changes."}, {"q": "Tension is equal because…", "o": ["rope and pulley are ideal", "every rope always has equal tension", "masses equal"], "a": 0, "explain": "Mass and pulley inertia assumptions matter."}], "practice": [{"q": "A smooth table block of 6 kg joins a 2 kg hanging mass. Find a and T.", "points": ["a = 2(9.8)/(6 + 2) = 2.45 m/s².", "T = 6a = 14.7 N.", "Check 19.6 − 14.7 = 2a."]}, {"q": "A 5 kg rough-table block with μs = 0.4 joins a 1.5 kg hanging mass, initially at rest. Determine whether it moves and actual friction.", "points": ["Maximum static friction = 0.4 × 5 × 9.8 = 19.6 N.", "Required friction = hanging weight = 14.7 N.", "It stays at rest because 14.7 < 19.6 N.", "Actual static friction and tension each equal 14.7 N."]}], "chapters": [["Recognise", "Identify objects, signs and regimes"], ["Build", "Construct the model and its limits"], ["Solve", "Follow explained original exam-style examples"], ["Practise", "Reason, calculate and transfer"]], "constants": "Use g = 9.80 m/s². Use SI units and stated idealisations. Practice questions are original exam-style teaching questions.", "summary": "A taut inextensible rope around a fixed ideal pulley makes the attached masses travel equal distances along their paths.", "focus": {"question": "A smooth table block of 6 kg joins a 2 kg hanging mass. Find a and T.", "points": ["a = 2(9.8)/(6 + 2) = 2.45 m/s².", "T = 6a = 14.7 N.", "Check 19.6 − 14.7 = 2a."], "claim": "masses"}};
s3.pages.forEach(p=>{p.html=p.html.replace('__DIAGRAM__',diagram('pulley')).replace('__DETAIL__',detail('pulley')).replace('__WORKED_DIAGRAM__',workedDiagram('pulley')).replace('__CHECK__',check('y11-friction-slopes-focus-3-guided',"Hanging mass accelerates down, so T\u2026",["is below mg", "equals mg", "exceeds mg"],0,["mg \u2212 T = ma > 0.", "mg \u2212 T = ma > 0.", "mg \u2212 T = ma > 0."])).replace('__NUMBER__',number('y11-friction-slopes-focus-3-numeric',"An ideal smooth table block 3 kg joins a hanging mass 1 kg. Find acceleration.",2.45,"m/s\u00b2","a = m2g/(m1 + m2) = 9.8/4 = 2.45 m/s\u00b2.",.02)).replace('__PAPER__',paper('Explain a model assumption'));if(p.html==='__PRACTICE__'){const x=s3.practice[p.practiceIndex];p.html='<div class="pp-page">'+P('<b>Original exam-style · '+x.points.length+' marks.</b> '+x.q)+paper('Your diagram, reasoning and calculations')+R('Explain the marking points',mark(x.points))+'</div>';}});C.register(s3);
const s4={"id": "y11-momentum-impulse-focus-1", "parent": "y11-momentum-impulse", "title": "Impulse and rebound: keep the signs", "shortTitle": "Impulse and rebound", "subtitle": "A ball brought to rest and a ball bounced back have different momentum changes even if incoming speeds match.", "pages": [{"chapter": 0, "title": "Catching versus bouncing", "html": "__DIAGRAM__<div class=\"pp-page\"><p>A ball brought to rest and a ball bounced back have different momentum changes even if incoming speeds match.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Momentum definition", "html": "<div class=\"pp-page\"><p>p = mv is a vector. In one dimension choose a positive axis and attach a sign to velocity.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Mass unit first", "html": "<div class=\"pp-page\"><p>Convert grams to kilograms before multiplying by m/s. A 200 g ball has mass 0.200 kg.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Momentum change order", "html": "<div class=\"pp-page\"><p>Δp = pfinal − pinitial = m(v − u), if mass is constant. Reversing subtraction reverses the impulse direction.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Impulse definition", "html": "<div class=\"pp-page\"><p>J = integral Fnet dt = Δp. For an average net force, J = Fnet,avg Δt.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Impulse units", "html": "<div class=\"pp-page\"><p>N·s = kg·m/s because N = kg·m/s². Impulse is not measured in newtons alone.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Stopping a positive-moving object", "html": "<div class=\"pp-page\"><p>If u > 0 and v = 0, Δp = −mu. The stopping impulse acts in the negative direction.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Rebound velocity is negative", "html": "<div class=\"pp-page\"><p>With towards the wall positive, departure away from the wall has v < 0. Do not insert the outgoing speed as a positive velocity.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Magnitude for rebound", "html": "<div class=\"pp-page\"><p>For incoming speed U and outgoing speed V, impulse magnitude is m(U + V), not m(U − V). Directions account for the sum.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Average net force", "html": "<div class=\"pp-page\"><p>Fnet,avg = m(v − u)/Δt. This force equals the total resultant averaged across the collision interval.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Time unit conversion", "html": "<div class=\"pp-page\"><p>A 20 ms contact lasts 0.020 s. Using 20 s would reduce the calculated force by a factor of 1000.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Force direction follows Δp", "html": "<div class=\"pp-page\"><p>A positive final velocity smaller than initial can still require a negative impulse. Do not infer impulse direction from final velocity alone.</p></div>", "type": "learn"}, {"chapter": 1, "title": "A brief collision", "html": "<div class=\"pp-page\"><p>Large force can act for a short time. The momentum change depends on the area or product, not force magnitude by itself.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Rebound compared with stop", "html": "<div class=\"pp-page\"><p>With the same incoming speed and mass, rebound adds the outgoing momentum magnitude and therefore requires a larger impulse magnitude than stopping.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Same impulse, different durations", "html": "__DETAIL__<div class=\"pp-page\"><p>Spreading a fixed momentum change over longer time lowers average net force. It does not reduce the required impulse.</p></div>", "type": "learn"}, {"chapter": 1, "title": "External impulse and system", "html": "<div class=\"pp-page\"><p>Momentum conservation is the special case of negligible external impulse on the chosen system. An individual bouncing ball receives a wall impulse and does not conserve its own momentum.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Ball and wall pair", "html": "<div class=\"pp-page\"><p>Contact impulses on ball and wall are equal and opposite over the same interaction time. Their velocity changes need not match because masses differ.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Gravity during contact", "html": "<div class=\"pp-page\"><p>If vertical, net impulse includes gravity as well as contact. For very short durations gravity may be small, but state the approximation.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Horizontal wall model", "html": "<div class=\"pp-page\"><p>For a level horizontal rebound, gravity and support can cancel vertically; horizontal net impulse can equal horizontal wall impulse if other horizontal forces are negligible.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Speed after a known impulse", "html": "<div class=\"pp-page\"><p>v = u + J/m. A negative J may slow, stop, or reverse the object depending on its magnitude.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Threshold for reversal", "html": "<div class=\"pp-page\"><p>For positive u, reversal requires J < −mu. Equality stops the object; a smaller negative magnitude only slows it.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Energy is a separate question", "html": "<div class=\"pp-page\"><p>Momentum change alone does not tell you kinetic energy change without initial and final speed. Rebound can lose energy even while impulse is large.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Squashing a ball", "html": "<div class=\"pp-page\"><p>Deformation changes contact time and force shape. The initial/final momenta still determine total impulse.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Original exam-style work", "html": "<div class=\"pp-page\"><p>The examples here are written teaching questions, not attributed to a past paper. State axes, signs and interval explicitly in exam working.</p></div>", "type": "learn"}, {"chapter": 2, "title": "Worked scenario: Horizontal rebound", "html": "__WORKED_DIAGRAM__<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 0.200 kg ball approaches a wall at +12.0 m/s and rebounds at −8.00 m/s in 0.0400 s.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Horizontal rebound", "html": "<div class=\"pp-page\"><p>Initial p = 0.200 × 12.0 = +2.40 kg·m/s; final p = 0.200 × (−8.00) = −1.60 kg·m/s. Δp = −1.60 − 2.40 = −4.00 N·s. Average horizontal force = −4.00/0.0400 = −100 N, away from wall. The negative sign communicates direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: A known braking impulse", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 2 kg trolley initially moves at +3 m/s. It receives a −10 N·s impulse. Find final velocity.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: A known braking impulse", "html": "<div class=\"pp-page\"><p>Initial p = +6 kg·m/s. Final p = 6 − 10 = −4 kg·m/s. v = −4/2 = −2 m/s. A −6 N·s impulse would stop it; −10 N·s exceeds that threshold and reverses it.</p></div>", "type": "worked"}, {"chapter": 3, "title": "Guided reasoning: identify the model", "html": "__CHECK__", "type": "practice"}, {"chapter": 3, "title": "Guided calculation: one step at a time", "html": "__NUMBER__", "type": "practice"}, {"chapter": 3, "title": "Independent: A 150 g ball with u = +10 m/s rebounds at −6 m/s during 30 ms.", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 0}, {"chapter": 3, "title": "Independent: A 0.5 kg ball stops from +8 m/s in 0.1 s. Compare its impulse ", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 1}, {"chapter": 3, "title": "Explain the limit of your answer", "html": "<div class=\"pp-page\"><p>The examples here are written teaching questions, not attributed to a past paper. State axes, signs and interval explicitly in exam working.</p><p>Write a short explanation tied to one worked example: name an assumption, explain which equation uses it, and describe a physical change that would require a new model. Keep force, impulse and velocity directions explicit.</p>__PAPER__</div>", "type": "practice"}], "bank": [{"q": "For rebound use outgoing…", "o": ["signed velocity", "positive speed only", "mass sign"], "a": 0, "explain": "Rebound reverses velocity direction."}, {"q": "Impulse units are…", "o": ["N·s", "N/s", "J/s"], "a": 0, "explain": "They are equivalent to kg·m/s."}, {"q": "Δp subtraction is…", "o": ["final minus initial", "initial minus final", "sum always"], "a": 0, "explain": "Use a consistent vector sign convention."}, {"q": "Longer time for same Δp means…", "o": ["smaller average force", "smaller impulse", "larger average force"], "a": 0, "explain": "Favg = Δp/Δt."}, {"q": "Negative impulse always…", "o": ["changes momentum negatively", "makes final velocity negative", "means negative mass"], "a": 0, "explain": "It may just slow a positive-moving object."}, {"q": "Individual ball momentum during wall impact…", "o": ["changes", "is conserved", "is zero"], "a": 0, "explain": "The wall exerts external impulse on the ball."}], "practice": [{"q": "A 150 g ball with u = +10 m/s rebounds at −6 m/s during 30 ms. Calculate impulse and average force.", "points": ["m = 0.150 kg; Δt = 0.030 s.", "Δp = 0.150[−6 − 10] = −2.40 N·s.", "Favg = −2.40/0.030 = −80.0 N.", "Direction away from the wall."]}, {"q": "A 0.5 kg ball stops from +8 m/s in 0.1 s. Compare its impulse with rebounding at −8 m/s.", "points": ["Stopping impulse = 0.5(0 − 8) = −4 N·s.", "Rebound impulse = 0.5(−8 − 8) = −8 N·s.", "Rebound magnitude is twice stopping magnitude.", "Same time gives forces −40 and −80 N."]}], "chapters": [["Recognise", "Identify objects, signs and regimes"], ["Build", "Construct the model and its limits"], ["Solve", "Follow explained original exam-style examples"], ["Practise", "Reason, calculate and transfer"]], "constants": "Use g = 9.80 m/s². Use SI units and stated idealisations. Practice questions are original exam-style teaching questions.", "summary": "A ball brought to rest and a ball bounced back have different momentum changes even if incoming speeds match.", "focus": {"question": "A 150 g ball with u = +10 m/s rebounds at −6 m/s during 30 ms. Calculate impulse and average force.", "points": ["m = 0.150 kg; Δt = 0.030 s.", "Δp = 0.150[−6 − 10] = −2.40 N·s.", "Favg = −2.40/0.030 = −80.0 N.", "Direction away from the wall."], "claim": "positive speed only"}};
s4.pages.forEach(p=>{p.html=p.html.replace('__DIAGRAM__',diagram('rebound')).replace('__DETAIL__',detail('rebound')).replace('__WORKED_DIAGRAM__',workedDiagram('rebound')).replace('__CHECK__',check('y11-momentum-impulse-focus-1-guided',"Impulse units are\u2026",["N\u00b7s", "N/s", "J/s"],0,["They are equivalent to kg\u00b7m/s.", "They are equivalent to kg\u00b7m/s.", "They are equivalent to kg\u00b7m/s."])).replace('__NUMBER__',number('y11-momentum-impulse-focus-1-numeric',"A 0.2 kg ball changes velocity from +5 to \u22125 m/s. Find signed impulse.",-2,"N\u00b7s","J = 0.2[\u22125 \u2212 (+5)] = \u22122 N\u00b7s.",.02)).replace('__PAPER__',paper('Explain a model assumption'));if(p.html==='__PRACTICE__'){const x=s4.practice[p.practiceIndex];p.html='<div class="pp-page">'+P('<b>Original exam-style · '+x.points.length+' marks.</b> '+x.q)+paper('Your diagram, reasoning and calculations')+R('Explain the marking points',mark(x.points))+'</div>';}});C.register(s4);
const s5={"id": "y11-momentum-impulse-focus-2", "parent": "y11-momentum-impulse", "title": "Force-time graphs: area, signs and average force", "shortTitle": "Force-time graphs", "subtitle": "The vertical axis is net force and the horizontal axis is time. The graph’s shape is not the object’s path.", "pages": [{"chapter": 0, "title": "The graph describes force history", "html": "__DIAGRAM__<div class=\"pp-page\"><p>The vertical axis is net force and the horizontal axis is time. The graph’s shape is not the object’s path.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Read net versus contact", "html": "<div class=\"pp-page\"><p>A graph labelled contact force excludes other forces. A net-force graph includes the vector sum. Impulse–momentum uses net force.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Area has impulse units", "html": "<div class=\"pp-page\"><p>Force times time gives N·s. Gradient would have N/s and does not give momentum change.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Rectangle pulse", "html": "<div class=\"pp-page\"><p>For constant force F over duration Δt, area J = FΔt. Use the interval width, not the clock time at its endpoint.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Triangle pulse", "html": "<div class=\"pp-page\"><p>If force rises from zero to Fpeak and returns to zero along straight sides, J = ½FpeakΔt.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Triangle peak is not average", "html": "<div class=\"pp-page\"><p>For this triangular pulse Favg = Fpeak/2. Multiplying the peak by the full duration doubles the true impulse.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Trapezium pulse", "html": "<div class=\"pp-page\"><p>For a straight-line force change from F1 to F2, J = ½(F1 + F2)Δt. Split at a zero crossing if asking unsigned area.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Piecewise stages", "html": "<div class=\"pp-page\"><p>Calculate one signed area for each interval, then add. Label boundaries to avoid counting a shared stage twice.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Negative area", "html": "<div class=\"pp-page\"><p>A region below the force-zero line gives negative impulse for the chosen axis. It subtracts from positive momentum change.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Zero net area", "html": "<div class=\"pp-page\"><p>Equal positive and negative impulses produce zero total momentum change, although momentum changed within the interval.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Final velocity", "html": "<div class=\"pp-page\"><p>v = u + J/m for fixed mass. The area gives velocity change only after dividing by mass.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Average across which interval?", "html": "<div class=\"pp-page\"><p>Favg = total signed impulse / total specified duration. Include gaps of zero force if they lie inside the requested interval.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Changing the time axis unit", "html": "<div class=\"pp-page\"><p>If time is in milliseconds, convert widths to seconds. Graph reading can be correct while units still create a factor-1000 error.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Peak and injury context", "html": "<div class=\"pp-page\"><p>Equal impulses can have different peaks and durations. Average force does not uniquely specify the peak or detailed force history.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Smooth curved pulse", "html": "__DETAIL__<div class=\"pp-page\"><p>For a curved graph, area can be estimated numerically using thin trapezia. More samples can improve approximation but measurement uncertainty remains.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Trapezoidal data estimate", "html": "<div class=\"pp-page\"><p>Between successive samples use ½(Fi + Fi+1)(ti+1 − ti). Sum all intervals with their signs.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Baseline correction", "html": "<div class=\"pp-page\"><p>A sensor offset adds a spurious rectangular area. Establish zero force before interpreting measured impulse.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Brief spike", "html": "<div class=\"pp-page\"><p>A tall narrow spike can have the same area as a low broad pulse. Compare areas rather than only heights.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Momentary zero force", "html": "<div class=\"pp-page\"><p>At Fnet = 0, instantaneous acceleration is zero, but velocity need not be zero. Do not read force as velocity.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Positive force on left-moving object", "html": "<div class=\"pp-page\"><p>Positive impulse increases signed velocity; it may slow a left-moving object before reversing it.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Check momentum independently", "html": "<div class=\"pp-page\"><p>Calculate m(v − u) from measured velocities and compare it with graph area. Disagreement prompts checking units, baseline and omitted forces.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Graph interpolation assumption", "html": "<div class=\"pp-page\"><p>Straight sides allow exact triangle/trapezium formulas. Sparse measurements only justify an approximation between samples.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Do not use kinetic energy area", "html": "<div class=\"pp-page\"><p>Force–time area is momentum change. Force–displacement area gives work. The horizontal axis determines the meaning.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Describe the interval physically", "html": "<div class=\"pp-page\"><p>Say which object, force, positive direction and start/end times your area refers to. A number without a boundary can be ambiguous.</p></div>", "type": "learn"}, {"chapter": 2, "title": "Worked scenario: Triangular pulse", "html": "__WORKED_DIAGRAM__<div class=\"pp-page\"><p><b>Original exam-style example.</b> A net-force triangle rises from 0 N at t = 0 to 100 N at 0.100 s and falls to zero at 0.200 s. A 2 kg trolley starts at rest.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Triangular pulse", "html": "<div class=\"pp-page\"><p>J = ½ × 100 × 0.200 = 10.0 N·s. Favg over the pulse = 10.0/0.200 = 50.0 N. Δv = 10.0/2 = 5.00 m/s. Final velocity +5.00 m/s. The 100 N peak is twice the average because the triangle occupies half the enclosing rectangle.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Positive and negative stages", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 1 kg cart starts at +1 m/s. Net force is +6 N from 0 to 2 s, then −4 N from 2 to 5 s.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Positive and negative stages", "html": "<div class=\"pp-page\"><p>First impulse = 6 × 2 = +12 N·s; second = −4 × 3 = −12 N·s. Total zero, so final velocity is +1 m/s. At 2 s, however, v = 1 + 12/1 = 13 m/s. Zero total area does not mean the cart’s velocity was constant throughout.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Measured trapezium", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> Force increases linearly from 20 N to 60 N over 0.050 s, then remains 60 N for 0.020 s.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Measured trapezium", "html": "<div class=\"pp-page\"><p>First area = ½(20 + 60)0.050 = 2.00 N·s. Second rectangle = 60 × 0.020 = 1.20 N·s. Total J = 3.20 N·s. Average over 0.070 s = 45.7 N. Divide by mass only if a velocity change is requested.</p></div>", "type": "worked"}, {"chapter": 3, "title": "Guided reasoning: identify the model", "html": "__CHECK__", "type": "practice"}, {"chapter": 3, "title": "Guided calculation: one step at a time", "html": "__NUMBER__", "type": "practice"}, {"chapter": 3, "title": "Independent: A triangular net-force pulse has peak 80 N and lasts 50 ms. A ", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 0}, {"chapter": 3, "title": "Independent: Net force is +10 N for 0.2 s, zero for 0.3 s, then −5 N for 0.", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 1}, {"chapter": 3, "title": "Explain the limit of your answer", "html": "<div class=\"pp-page\"><p>Say which object, force, positive direction and start/end times your area refers to. A number without a boundary can be ambiguous.</p><p>Write a short explanation tied to one worked example: name an assumption, explain which equation uses it, and describe a physical change that would require a new model. Keep force, impulse and velocity directions explicit.</p>__PAPER__</div>", "type": "practice"}], "bank": [{"q": "Force-time area gives…", "o": ["impulse", "work", "acceleration directly"], "a": 0, "explain": "N times seconds equals momentum units."}, {"q": "Triangular pulse average is…", "o": ["half peak", "equal peak", "twice peak"], "a": 0, "explain": "Its area is half the enclosing rectangle."}, {"q": "A below-axis area is…", "o": ["negative impulse", "negative mass", "always a reversal"], "a": 0, "explain": "Direction comes from the force sign."}, {"q": "Zero total impulse implies…", "o": ["same final momentum", "constant momentum throughout", "no forces throughout"], "a": 0, "explain": "Intermediate momentum can vary."}, {"q": "An included zero-force gap…", "o": ["counts in average duration", "adds impulse", "must be removed"], "a": 0, "explain": "It adds time but zero area."}, {"q": "Force-displacement area gives…", "o": ["work", "impulse", "velocity"], "a": 0, "explain": "The horizontal axis changes the physical meaning."}], "practice": [{"q": "A triangular net-force pulse has peak 80 N and lasts 50 ms. A 0.5 kg cart initially has v = −2 m/s. Find J and final v.", "points": ["Duration = 0.050 s.", "J = ½ × 80 × 0.050 = +2.00 N·s.", "Δv = 2/0.5 = +4 m/s.", "Final v = −2 + 4 = +2 m/s."]}, {"q": "Net force is +10 N for 0.2 s, zero for 0.3 s, then −5 N for 0.1 s. Find impulse and average over all 0.6 s.", "points": ["Areas +2.0, 0, −0.5 N·s.", "Total J = +1.5 N·s.", "Favg = 1.5/0.6 = +2.5 N.", "Include the zero-force gap in total duration."]}], "chapters": [["Recognise", "Identify objects, signs and regimes"], ["Build", "Construct the model and its limits"], ["Solve", "Follow explained original exam-style examples"], ["Practise", "Reason, calculate and transfer"]], "constants": "Use g = 9.80 m/s². Use SI units and stated idealisations. Practice questions are original exam-style teaching questions.", "summary": "The vertical axis is net force and the horizontal axis is time. The graph’s shape is not the object’s path.", "focus": {"question": "A triangular net-force pulse has peak 80 N and lasts 50 ms. A 0.5 kg cart initially has v = −2 m/s. Find J and final v.", "points": ["Duration = 0.050 s.", "J = ½ × 80 × 0.050 = +2.00 N·s.", "Δv = 2/0.5 = +4 m/s.", "Final v = −2 + 4 = +2 m/s."], "claim": "work"}};
s5.pages.forEach(p=>{p.html=p.html.replace('__DIAGRAM__',diagram('graph')).replace('__DETAIL__',detail('graph')).replace('__WORKED_DIAGRAM__',workedDiagram('graph')).replace('__CHECK__',check('y11-momentum-impulse-focus-2-guided',"Triangular pulse average is\u2026",["half peak", "equal peak", "twice peak"],0,["Its area is half the enclosing rectangle.", "Its area is half the enclosing rectangle.", "Its area is half the enclosing rectangle."])).replace('__NUMBER__',number('y11-momentum-impulse-focus-2-numeric',"A triangular pulse has peak 60 N and duration 0.2 s. Find impulse.",6,"N\u00b7s","J = half base \u00d7 height = 0.5 \u00d7 0.2 \u00d7 60 = 6 N\u00b7s.",.02)).replace('__PAPER__',paper('Explain a model assumption'));if(p.html==='__PRACTICE__'){const x=s5.practice[p.practiceIndex];p.html='<div class="pp-page">'+P('<b>Original exam-style · '+x.points.length+' marks.</b> '+x.q)+paper('Your diagram, reasoning and calculations')+R('Explain the marking points',mark(x.points))+'</div>';}});C.register(s5);
const s6={"id": "y11-momentum-impulse-focus-3", "parent": "y11-momentum-impulse", "title": "Contact and net force: landing, catching and safety", "shortTitle": "Contact and net force", "subtitle": "For the same initial and final velocities, landing requires the same net impulse. Padding mainly changes how that impulse is delivered over time.", "pages": [{"chapter": 0, "title": "A soft landing still changes momentum", "html": "__DIAGRAM__<div class=\"pp-page\"><p>For the same initial and final velocities, landing requires the same net impulse. Padding mainly changes how that impulse is delivered over time.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Choose the person as object", "html": "<div class=\"pp-page\"><p>A landing person feels upward ground contact and downward gravity. These real forces combine to produce the net stopping force.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Up positive for a falling object", "html": "<div class=\"pp-page\"><p>Incoming downward velocity is negative. If it stops, Δv = 0 − (−U) = +U, hence net impulse is upward.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Weight acts throughout contact", "html": "<div class=\"pp-page\"><p>Gravity impulse is −mgΔt. It does not vanish just because the contact force is much larger.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Contact impulse equation", "html": "<div class=\"pp-page\"><p>Jcontact − mgΔt = m(v − u). Thus Jcontact = m(v − u) + mgΔt when other vertical forces are absent.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Average contact force", "html": "<div class=\"pp-page\"><p>Naverage = m(v − u)/Δt + mg. Net average force is the first term only.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Ground force versus apparent weight", "html": "<div class=\"pp-page\"><p>In a landing, ground contact changes rapidly. A static mg calculation cannot predict the stopping force.</p></div>", "type": "learn"}, {"chapter": 0, "title": "Catch a falling ball", "html": "<div class=\"pp-page\"><p>The hand provides upward contact force while weight remains downward. Use the ball’s momentum change to find the net impulse, then add gravity to recover hand force.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Bend knees and extend stopping time", "html": "<div class=\"pp-page\"><p>For matched momentum change, increasing duration reduces the dynamic mΔv/Δt term. Weight remains as a baseline in the average contact force.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Time cannot describe everything", "html": "<div class=\"pp-page\"><p>Injury also depends on peak, force distribution, body posture, deformation and vulnerable tissue. A simple average-force calculation is not a complete injury prediction.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Stopping distance route", "html": "<div class=\"pp-page\"><p>If acceleration is approximately constant, v² = u² + 2aΔy. Use signed vertical displacement to find a, then calculate contact force.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Time and distance consistency", "html": "<div class=\"pp-page\"><p>For uniform stopping from speed U to zero, distance magnitude d = UΔt/2. Use this relationship to check equivalent constant-force models.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Rebound adds momentum change", "html": "<div class=\"pp-page\"><p>A downward speed U followed by upward speed V gives Δv = V + U. A bounce can require a larger net impulse than a non-rebounding stop.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Horizontal vehicle stop", "html": "<div class=\"pp-page\"><p>For an occupant, a horizontal belt or airbag supplies stopping contact force. Vertical normal and weight approximately balance in the simple straight-line model.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Seat belt and airbag", "html": "__DETAIL__<div class=\"pp-page\"><p>A belt restrains displacement and an airbag can distribute force and extend deceleration. Both must be interpreted within the same occupant stopping event.</p></div>", "type": "learn"}, {"chapter": 1, "title": "No belt model warning", "html": "<div class=\"pp-page\"><p>Without restraint an occupant initially keeps moving when the vehicle slows; the occupant later stops via another interaction. Do not assume occupant a equals vehicle a automatically.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Crumple-zone system", "html": "<div class=\"pp-page\"><p>Vehicle deformation can lengthen the vehicle stopping interval. Occupant behaviour also depends on restraints and interior contacts.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Impulse pair during catching", "html": "<div class=\"pp-page\"><p>The ball pushes downward on the hand while the hand pushes upward on the ball with equal contact-force magnitude. The hand also interacts with arm and body.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Peak from a triangular contact pulse", "html": "<div class=\"pp-page\"><p>If contact force is a zero-baseline triangle, Fpeak = 2Jcontact/Δt. This shape assumption must be stated; it is not universal.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Longer time contact impulse changes slightly", "html": "<div class=\"pp-page\"><p>For fixed Δp, Jcontact = Δp + mgΔt rises with time while average contact force falls. Net impulse remains fixed.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Gravity neglect criterion", "html": "<div class=\"pp-page\"><p>Compare mgΔt with |Δp|. Neglecting gravity is justified only when its impulse is small relative to the required change.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Compare forces at fixed mass and speed", "html": "<div class=\"pp-page\"><p>A tenfold increase in stopping time divides the dynamic net force by ten, but total vertical contact force does not divide exactly by ten due to mg.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Separate system and interval", "html": "<div class=\"pp-page\"><p>For the whole Earth-plus-person system, contact is internal. For the person alone it is external and changes their momentum.</p></div>", "type": "learn"}, {"chapter": 1, "title": "Evaluate claims rather than slogans", "html": "<div class=\"pp-page\"><p>“Padding reduces momentum change” is false for identical start/end velocities. A precise explanation is that padding can extend stopping time and lower average net force.</p></div>", "type": "learn"}, {"chapter": 2, "title": "Worked scenario: Person landing without rebound", "html": "__WORKED_DIAGRAM__<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 60 kg person lands at −4 m/s and stops in 0.20 s. Up positive. Find net and ground average forces.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Person landing without rebound", "html": "<div class=\"pp-page\"><p>Δp = 60[0 − (−4)] = +240 N·s. Net average = 240/0.20 = 1200 N up. Weight = 588 N down, so ground average = 1200 + 588 = 1788 N up. If time increases to 0.50 s, net average = 480 N and ground average = 1068 N. The net impulse stays 240 N·s.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Catching a falling ball", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 0.20 kg ball falls at −5 m/s and is stopped by a hand in 0.10 s. Find hand impulse and average hand force.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Catching a falling ball", "html": "<div class=\"pp-page\"><p>Δp = 0.20 × 5 = +1.00 N·s. Gravity impulse = −0.20 × 9.80 × 0.10 = −0.196 N·s. Hand impulse must be +1.196 N·s; hand average = 11.96 N. Net average is only 10.0 N. If gravity is neglected the hand force is underestimated by 1.96 N.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Worked scenario: Landing distance model", "html": "<div class=\"pp-page\"><p><b>Original exam-style example.</b> A 50 kg person lands at downward speed 3 m/s and stops over downward displacement 0.30 m at constant acceleration.</p><p>Before calculating, draw the selected object or system, choose an axis and state the contact/rope/time assumptions. Predict the result direction.</p></div>", "type": "worked"}, {"chapter": 2, "title": "Explain the solution: Landing distance model", "html": "<div class=\"pp-page\"><p>Up positive: u = −3 m/s; Δy = −0.30 m. 0 = 9 + 2a(−0.30), so a = +15 m/s². Ground force = 50(15 + 9.8) = 1240 N. Stop time = [0 − (−3)]/15 = 0.20 s; average-speed distance = 1.5 × 0.20 = 0.30 m, consistent.</p></div>", "type": "worked"}, {"chapter": 3, "title": "Guided reasoning: identify the model", "html": "__CHECK__", "type": "practice"}, {"chapter": 3, "title": "Guided calculation: one step at a time", "html": "__NUMBER__", "type": "practice"}, {"chapter": 3, "title": "Independent: A 70 kg person lands at −3 m/s and stops in 0.30 s. Calculate ", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 0}, {"chapter": 3, "title": "Independent: A 0.5 kg ball arrives downward at 6 m/s and leaves upward at 2", "html": "__PRACTICE__", "type": "practice", "practiceIndex": 1}, {"chapter": 3, "title": "Explain the limit of your answer", "html": "<div class=\"pp-page\"><p>“Padding reduces momentum change” is false for identical start/end velocities. A precise explanation is that padding can extend stopping time and lower average net force.</p><p>Write a short explanation tied to one worked example: name an assumption, explain which equation uses it, and describe a physical change that would require a new model. Keep force, impulse and velocity directions explicit.</p>__PAPER__</div>", "type": "practice"}], "bank": [{"q": "Padding for the same u and v mainly changes…", "o": ["stopping duration", "required Δp", "object mass"], "a": 0, "explain": "Longer duration lowers average net force."}, {"q": "Vertical ground force equals…", "o": ["net upward force plus weight", "net force only", "weight minus upward net force"], "a": 0, "explain": "N − mg = ma."}, {"q": "A downward ball stopping has impulse…", "o": ["upward", "downward", "zero"], "a": 0, "explain": "Final minus initial velocity is positive for up-positive axes."}, {"q": "Neglect gravity only when…", "o": ["its impulse is small", "contact occurs", "motion is downward"], "a": 0, "explain": "Compare mgΔt with momentum change."}, {"q": "Average force alone predicts injury…", "o": ["incompletely", "exactly", "without any context"], "a": 0, "explain": "Peak and distribution also matter."}, {"q": "Longer vertical stopping time at fixed Δp makes contact impulse…", "o": ["slightly larger", "zero", "identical always"], "a": 0, "explain": "Contact must also balance the longer gravity impulse."}], "practice": [{"q": "A 70 kg person lands at −3 m/s and stops in 0.30 s. Calculate net impulse, average net force and ground force.", "points": ["Δp = 70[0 − (−3)] = +210 N·s.", "Average net = 210/0.30 = +700 N.", "Weight = 686 N downward.", "Ground average = 700 + 686 = 1386 N upward."]}, {"q": "A 0.5 kg ball arrives downward at 6 m/s and leaves upward at 2 m/s during 0.05 s. Find average contact force.", "points": ["Up positive u = −6; v = +2 m/s.", "Δp = 0.5(2 + 6) = +4 N·s.", "Average net force = 4/0.05 = 80 N upward.", "Contact average = 80 + 4.9 = 84.9 N upward."]}], "chapters": [["Recognise", "Identify objects, signs and regimes"], ["Build", "Construct the model and its limits"], ["Solve", "Follow explained original exam-style examples"], ["Practise", "Reason, calculate and transfer"]], "constants": "Use g = 9.80 m/s². Use SI units and stated idealisations. Practice questions are original exam-style teaching questions.", "summary": "For the same initial and final velocities, landing requires the same net impulse. Padding mainly changes how that impulse is delivered over time.", "focus": {"question": "A 70 kg person lands at −3 m/s and stops in 0.30 s. Calculate net impulse, average net force and ground force.", "points": ["Δp = 70[0 − (−3)] = +210 N·s.", "Average net = 210/0.30 = +700 N.", "Weight = 686 N downward.", "Ground average = 700 + 686 = 1386 N upward."], "claim": "required Δp"}};
s6.pages.forEach(p=>{p.html=p.html.replace('__DIAGRAM__',diagram('contact')).replace('__DETAIL__',detail('contact')).replace('__WORKED_DIAGRAM__',workedDiagram('contact')).replace('__CHECK__',check('y11-momentum-impulse-focus-3-guided',"Vertical ground force equals\u2026",["net upward force plus weight", "net force only", "weight minus upward net force"],0,["N \u2212 mg = ma.", "N \u2212 mg = ma.", "N \u2212 mg = ma."])).replace('__NUMBER__',number('y11-momentum-impulse-focus-3-numeric',"A 50 kg person stops from \u22122 m/s in 0.2 s. Find average ground force.",990,"N","\u0394p/\u0394t = 50 \u00d7 2/0.2 = 500 N up; add mg = 490 N to get 990 N.",.02)).replace('__PAPER__',paper('Explain a model assumption'));if(p.html==='__PRACTICE__'){const x=s6.practice[p.practiceIndex];p.html='<div class="pp-page">'+P('<b>Original exam-style · '+x.points.length+' marks.</b> '+x.q)+paper('Your diagram, reasoning and calculations')+R('Explain the marking points',mark(x.points))+'</div>';}});C.register(s6);
})();
